contract InvMutTest {
    C c;
    uint calls;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0 && tos.length <= 3);
        calls = 0;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && calls == tos.length);
    }

    fallback() external payable {
        calls++;
        assembly {
            mstore(0x00, 0x01)
            return(0x1c, 0x04)
        }
    }

    receive() external payable {}
}
